export * as Scrim from './scrim.tsx';
export type {
  ContentOwnProps as ScrimContentOwnProps,
  ContentProps as ScrimContentProps,
  LayerOwnProps as ScrimLayerOwnProps,
  LayerProps as ScrimLayerProps,
} from './scrim.tsx';

@layer hj.components {
  /* Customise: --hj-scrim-radius · --hj-scrim-strength · --hj-scrim-extent · --hj-scrim-color */
  .hj-scrim {
    position: relative;
    display: block;
    overflow: hidden;
    isolation: isolate;
    border-radius: var(--hj-scrim-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
  }
  .hj-scrim > img,
  .hj-scrim > picture,
  .hj-scrim > video {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  /*
   * One RGB, fading by opacity only (color-mix with transparent keeps the hue; gradients
   * interpolate premultiplied), along an eased five-stop curve so the scrim has no visible edge.
   */
  .hj-scrim-layer {
    --_c: var(--hj-scrim-color, var(--hj-scrim));
    --_a: var(--hj-scrim-strength, 72%);
    --_x: var(--hj-scrim-extent, 64%);
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background: linear-gradient(
      to top,
      color-mix(in srgb, var(--_c) var(--_a), transparent) 0%,
      color-mix(in srgb, var(--_c) calc(var(--_a) * 0.82), transparent) calc(var(--_x) * 0.25),
      color-mix(in srgb, var(--_c) calc(var(--_a) * 0.5), transparent) calc(var(--_x) * 0.55),
      color-mix(in srgb, var(--_c) calc(var(--_a) * 0.18), transparent) calc(var(--_x) * 0.82),
      color-mix(in srgb, var(--_c) 0%, transparent) var(--_x)
    );
  }
  .hj-scrim-layer[data-edge='top'] {
    background: linear-gradient(
      to bottom,
      color-mix(in srgb, var(--_c) var(--_a), transparent) 0%,
      color-mix(in srgb, var(--_c) calc(var(--_a) * 0.82), transparent) calc(var(--_x) * 0.25),
      color-mix(in srgb, var(--_c) calc(var(--_a) * 0.5), transparent) calc(var(--_x) * 0.55),
      color-mix(in srgb, var(--_c) calc(var(--_a) * 0.18), transparent) calc(var(--_x) * 0.82),
      color-mix(in srgb, var(--_c) 0%, transparent) var(--_x)
    );
  }
  .hj-scrim-layer[data-edge='full'] {
    background: color-mix(in srgb, var(--_c) var(--_a), transparent);
  }

  /* Over imagery ink is always light: re-point the ink tokens at on-scrim inside. */
  .hj-scrim-content {
    --hj-fg: var(--hj-on-scrim);
    --hj-fg-dim: color-mix(in srgb, var(--hj-on-scrim) 80%, transparent);
    --hj-fg-mute: color-mix(in srgb, var(--hj-on-scrim) 66%, transparent);
    --hj-line: color-mix(in srgb, var(--hj-on-scrim) 22%, transparent);
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 2;
    padding: var(--hj-space-4) var(--hj-space-5) var(--hj-space-5);
    color: var(--hj-fg);
  }
  .hj-scrim-content[data-edge='top'] {
    top: 0;
    bottom: auto;
    padding: var(--hj-space-4);
  }
  .hj-scrim-content[data-edge='center'] {
    top: 0;
    display: grid;
    place-content: center;
    text-align: center;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

/** The frame: holds the image, the layer and the content; clips them to its corners. */
export const Root: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Scrim.Root',
  'hj-scrim',
);

/** Props hanji adds to the gradient layer. */
export interface LayerOwnProps {
  /** Where the dark sits: bottom (titles), top (chrome over a hero), or full (text anywhere). */
  edge?: 'bottom' | 'top' | 'full';
  /** Darkness at the edge, 0–1. @default 0.72 */
  strength?: number;
  /** How far the fade reaches, as a CSS length or %. @default '64%' */
  extent?: string;
  /**
   * The colour that fades. Default the scrim token (black). Pass the art's own deep colour to
   * keep the fade in its hue — it only ever changes opacity, so it never greys.
   */
  color?: string;
  render?: useRender.RenderProp;
}

export interface LayerProps
  extends LayerOwnProps, Omit<React.ComponentProps<'span'>, 'className' | 'children'> {
  className?: string;
}

/**
 * The gradient. One RGB fading by opacity along an eased curve (five stops), so the edge of the
 * scrim is never visible. Decorative: aria-hidden.
 */
export function Layer(props: LayerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    edge = 'bottom',
    strength = 0.72,
    extent,
    color,
    render,
    className,
    style,
    ...rest
  } = withDefaults(config, 'Scrim.Layer', props);
  const a = Math.min(1, Math.max(0, strength));
  const vars = {
    '--hj-scrim-strength': `${Math.round(a * 1000) / 10}%`,
    ...(extent ? { '--hj-scrim-extent': extent } : null),
    ...(color ? { '--hj-scrim-color': color } : null),
    ...style,
  } as React.CSSProperties;
  return useRender({
    render,
    defaultTagName: 'span',
    props: {
      'aria-hidden': true,
      ...rest,
      style: vars,
      'data-edge': edge,
      className: cls(config, 'Scrim.Layer', 'hj-scrim-layer', className) as string | undefined,
    },
  });
}

/** Props hanji adds to the content block. */
export interface ContentOwnProps {
  /** Where the content sits; match the Layer's edge. @default 'bottom' */
  edge?: 'bottom' | 'top' | 'center';
  render?: useRender.RenderProp;
}

export interface ContentProps
  extends ContentOwnProps, Omit<React.ComponentProps<'div'>, 'className'> {
  className?: string;
}

/**
 * Content over the image. Ink inside is always light: the fg tokens are re-pointed at on-scrim,
 * so hanji text and controls placed here read correctly on every paper.
 */
export function Content(props: ContentProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    edge = 'bottom',
    render,
    className,
    ...rest
  } = withDefaults(config, 'Scrim.Content', props);
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...rest,
      'data-edge': edge,
      className: cls(config, 'Scrim.Content', 'hj-scrim-content', className) as string | undefined,
    },
  });
}
